def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [sorted_intervals[0][:]]

    for current in sorted_intervals[1:]:
        if current[0] <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], current[1])
        else:
            merged.append(current[:])

    return merged

import heapq

def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in set(edges):
        adj[src].add(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    batches = []
    current_batch = []
    current_weight = 0
    for name, w in items:
        if w <= 0 or w > limit:
            raise ValueError
        if current_weight + w > limit:
            batches.append(current_batch)
            current_batch = []
            current_weight = 0
        current_batch.append(name)
        current_weight += w
    if current_batch:
        batches.append(current_batch)
    return batches

import re

def parse_env(text):
    result = {}
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line: {line}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_pattern.fullmatch(key):
            raise ValueError(f"Invalid key: {key}")

        if len(value) >= 2 and ((value[0] == '"' and value[-1] == '"') or (value[0] == "'" and value[-1] == "'")):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    buffer = b""
    current_data = []
    events = []

    for chunk in chunks:
        buffer += chunk
        while b"\n" in buffer:
            idx = buffer.find(b"\n")
            line_bytes = buffer[:idx]
            if line_bytes.endswith(b"\r"):
                line_bytes = line_bytes[:-1]
            buffer = buffer[idx+1:]

            line = line_bytes.decode("utf-8")

            if not line:
                if current_data:
                    payload = "\n".join(current_data)
                    if payload == "[DONE]":
                        return events
                    events.append(payload)
                    current_data = []
            elif line.startswith("data:"):
                val = line[5:]
                if val.startswith(" "):
                    val = val[1:]
                current_data.append(val)

    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Arguments must be nonnegative")
    if base == 0 or cap == 0:
        return 0.0

    # base * 2**attempt >= cap  <=>  attempt >= log2(cap) - log2(base)
    # Using difference of logs avoids overflow when cap/base is huge.
    threshold = math.log2(cap) - math.log2(base)

    if attempt >= threshold:
        return float(cap)
    return float(base) * (2 ** attempt)

def fifo_admit(active, queued, budget, slots):
    if any(r > budget for r in queued):
        raise ValueError("Reservation exceeds budget")
    used_tokens = sum(active)
    used_slots = len(active)
    admitted = []
    for r in queued:
        if used_tokens + r <= budget and used_slots + 1 <= slots:
            admitted.append(r)
            used_tokens += r
            used_slots += 1
        else:
            break
    return admitted, queued[len(admitted):]
